-- Changelog-item voor de Vastleggen-knop op een contactpersoonkaart (commit 10fd8a41, CI groen).
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-21','verbeterd','Commercieel','Vastleggen kan nu ook vanaf een contactpersoon',
   'De knop Vastleggen stond alleen bij een opdrachtgever. Zoek je iemand op omdat je hém spreekt, dan kun je nu ook op zijn eigen kaart een gespreksnotitie, een verkoopkans of een actie vastleggen — met die persoon al ingevuld, dus je hoeft hem niet meer op te zoeken in een lijst. Werkt hij bij meerdere opdrachtgevers, dan vraagt het scherm bij welke het hoort.');
